module game_solver #(parameter N=8, parameter MAX_OPTIONS=8) (\n    input wire clk,\n    input wire rst_n,\n    input wire load_en,\n    input wire [2:0] load_pos,\n    input wire [2:0] load_option_idx,\n    input wire [N-1:0] load_option_mask,\n    input wire compute,\n    input wire [2:0] target,\n    input wire [2:0] start,\n    output reg [3:0] distance,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] STATE_IDLE        = 4'd0;\n    localparam [3:0] STATE_INIT        = 4'd1;\n    localparam [3:0] STATE_START_ROUND = 4'd2;\n    localparam [3:0] STATE_CHECK_POS   = 4'd3;\n    localparam [3:0] STATE_CHECK_OPT   = 4'd4;\n    localparam [3:0] STATE_NEXT_OPT    = 4'd5;\n    localparam [3:0] STATE_NEXT_POS    = 4'd6;\n    localparam [3:0] STATE_AFTER_ROUND = 4'd7;\n    localparam [3:0] STATE_OUTPUT      = 4'd8;\n\n    // Game description storage\n    reg [N-1:0] option_masks [0:N-1][0:MAX_OPTIONS-1];\n    reg option_valid [0:N-1][0:MAX_OPTIONS-1];\n\n    // Computation state\n    reg [3:0] dist [0:N-1];\n    reg [3:0] next_dist [0:N-1];\n    reg [2:0] round;\n    reg [2:0] p;\n    reg [2:0] opt;\n    reg updated;\n    reg [3:0] state;\n\n    integer i, j, k;  // Loop indices\n\n    // Load logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            for (i = 0; i < N; i = i + 1) begin\n                for (j = 0; j < MAX_OPTIONS; j = j + 1) begin\n                    option_valid[i][j] <= 1'b0;\n                end\n            end\n        end else if (load_en) begin\n            option_masks[load_pos][load_option_idx] <= load_option_mask;\n            option_valid[load_pos][load_option_idx] <= 1'b1;\n        end\n    end\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= STATE_IDLE;\n            done <= 1'b0;\n            distance <= 4'd0;\n            round <= 3'd0;\n            p <= 3'd0;\n            opt <= 3'd0;\n            updated <= 1'b0;\n\n            for (i = 0; i < N; i = i + 1) begin\n                dist[i] <= 4'hF;\n                next_dist[i] <= 4'hF;\n            end\n        end else begin\n            case (state)\n                STATE_IDLE: begin\n                    done <= 1'b0;\n                    if (compute) begin\n                        state <= STATE_INIT;\n                    end\n                end\n\n                STATE_INIT: begin\n                    for (i = 0; i < N; i = i + 1) begin\n                        dist[i] <= 4'hF;\n                    end\n                    dist[target] <= 4'd0;\n                    round <= 3'd1;\n                    state <= STATE_START_ROUND;\n                end\n\n                STATE_START_ROUND: begin\n                    for (i = 0; i < N; i = i + 1) begin\n                        next_dist[i] <= dist[i];\n                    end\n                    updated <= 1'b0;\n                    p <= 3'd0;\n                    state <= STATE_CHECK_POS;\n                end\n\n                STATE_CHECK_POS: begin\n                    if (p == 3'(N)) begin\n                        state <= STATE_AFTER_ROUND;\n                    end else if (dist[p] != 4'hF) begin\n                        p <= p + 3'd1;\n                    end else begin\n                        opt <= 3'd0;\n                        state <= STATE_CHECK_OPT;\n                    end\n                end\n\n                STATE_CHECK_OPT: begin\n                    if (opt == 3'(MAX_OPTIONS)) begin\n                        p <= p + 3'd1;\n                        state <= STATE_CHECK_POS;\n                    end else begin\n                        if (option_valid[p][opt]) begin\n                            // Check option validity\n                            reg valid_option;\n                            valid_option = 1'b1;\n                            for (k = 0; k < N; k = k + 1) begin\n                                if (option_masks[p][opt][k]) begin\n                                    if (dist[k] == 4'hF) begin\n                                        valid_option = 1'b0;\n                                    end\n                                end\n                            end\n\n                            if (valid_option) begin\n                                next_dist[p] <= round;\n                                updated <= 1'b1;\n                                p <= p + 3'd1;\n                                state <= STATE_CHECK_POS;\n                            end else begin\n                                opt <= opt + 3'd1;\n                            end\n                        end else begin\n                            opt <= opt + 3'd1;\n                        end\n                    end\n                end\n\n                STATE_AFTER_ROUND: begin\n                    if (updated && (round < 3'(N))) begin\n                        for (i = 0; i < N; i = i + 1) begin\n                            dist[i] <= next_dist[i];\n                        end\n                        round <= round + 3'd1;\n                        state <= STATE_START_ROUND;\n                    end else begin\n                        state <= STATE_OUTPUT;\n                    end\n                end\n\n                STATE_OUTPUT: begin\n                    distance <= dist[start];\n                    done <= 1'b1;\n                    state <= STATE_IDLE;\n                end\n\n                default: state <= STATE_IDLE;\n            endcase\n        end\n    end\nendmodule